15-ee545915bb39", "type": "subtopic", "title": "Historiographic intervention", "children": [{"id": "8b941437-6831-4929-93c0-dd19d157bad7", "type": "concept", "title": "Annotated bibliography"}, {"id": "f43e9e32-624b-41e2-a4eb-aacea72723f6", "type": "concept", "title": "Schools of interpretation"}, {"id": "cea92bbf-38c5-4464-87fd-4c530b07ca3a", "type": "concept", "title": "Argument positioning"}], "description": "Students learn to identify what scholars have argued and where their project contributes."}, {"id": "190e52e8-5cb6-4836-a5e4-5a80a3b86b76", "type": "subtopic", "title": "Digital and public history options", "children": [{"id": "33acb058-d288-4a23-8753-1655fdab386c", "type": "concept", "title": "GIS and spatial history"}, {"id": "4988c79d-8230-497f-940a-51551661acd4", "type": "concept", "title": "Text mining and metadata"}, {"id": "08d3300b-8a1c-460f-9a48-2ea6afc37e5e", "type": "concept", "title": "Public-facing exhibit design"}], "description": "This subtopic lets students use maps, timelines, datasets, exhibits, or visual analysis when appropriate."}]}], "dbBacked": true}$asiajson$::jsonb,
