values
  ('bf579dab-bcb7-4252-aca8-7d81250cb2b6', 'd2e3f4a5-6b7c-4d92-9e12-2f3a4b5c6d32', null, 'topic'::public.curated_course_node_type, 'Framing Asian History: Regions, Scales, Sources, and Historiography', 'This opening section gives students the intellectual map for the course. The point is to avoid treating Asia as a single civilization or a backdrop for Western expansion, and instead to ask how historians construct regions, periods, archives, and arguments.', 0),
  ('1f8ee1ec-7046-4e2f-ade3-6fadd56a2a0f', 'd2e3f4a5-6b7c-4d92-9e12-2f3a4b5c6d32', 'bf579dab-bcb7-4252-aca8-7d81250cb2b6', 'subtopic'::public.curated_course_node_type, 'Asia as a historical category', 'Students learn why East, South, Southeast, Central, and West Asia are useful but imperfect analytical labels.', 0),
  ('9e32dc31-db71-42d8-a36b-7917b6856782', 'd2e3f4a5-6b7c-4d92-9e12-2f3a4b5c6d32', '1f8ee1ec-7046-4e2f-ade3-6fadd56a2a0f', 'concept'::public.curated_course_node_type, 'Area studies and its critiques', null, 0),
  ('effdbaaf-3d46-43a2-a0ad-1c8f43655918', 'd2e3f4a5-6b7c-4d92-9e12-2f3a4b5c6d32', '1f8ee1ec-7046-4e2f-ade3-6fadd56a2a0f', 'concept'::public.curated_course_node_type, 'Continental, maritime, and borderland perspectives', null, 1),
  ('96d4e0d7-64a5-4a7e-b5e9-95650a32417b', 'd2e3f4a5-6b7c-4d92-9e12-2f3a4b5c6d32', '1f8ee1ec-7046-4e2f-ade3-6fadd56a2a0f', 'concept'::public.curated_course_node_type, 'Avoiding civilizational essentialism', null, 2),
  ('e55863af-e1c9-4634-b076-d5a24f42efe1', 'd2e3f4a5-6b7c-4d92-9e12-2f3a4b5c6d32', 'bf579dab-bcb7-4252-aca8-7d81250cb2b6', 'subtopic'::public.curated_course_node_type, 'Historical scale and comparison', 'The gist is to move confidently between village, dynasty, empire, ocean, diaspora, and global system.', 1),
  ('78be1e9d-07dc-4f47-b7de-f63c5fb29eea', 'd2e3f4a5-6b7c-4d92-9e12-2f3a4b5c6d32', 'e55863af-e1c9-4634-b076-d5a24f42efe1', 'concept'::public.curated_course_node_type, 'Local case studies', null, 0),
