  ('3ed07e68-1035-4d33-b2da-85083545f975', 'd2e3f4a5-6b7c-4d92-9e12-2f3a4b5c6d32', '07f91800-832c-46df-b531-d5f64370cb83', 'concept'::public.curated_course_node_type, 'Subaltern and postcolonial approaches', null, 2),
  ('861b90c7-f93b-47d1-849a-1c5227dbe9b2', 'd2e3f4a5-6b7c-4d92-9e12-2f3a4b5c6d32', null, 'topic'::public.curated_course_node_type, 'Ancient and Classical Foundations: South, East, Southeast, and Central Asia', 'This section establishes the deep structures that later states and societies inherited, contested, and reworked. Students focus on political formation, writing, social hierarchy, and exchange rather than memorizing dynasties in isolation.', 1),
  ('1c14e279-b4c5-4af2-823a-6865ec4ca46b', 'd2e3f4a5-6b7c-4d92-9e12-2f3a4b5c6d32', '861b90c7-f93b-47d1-849a-1c5227dbe9b2', 'subtopic'::public.curated_course_node_type, 'Early urbanism and states', 'The point is to compare how early complex societies organized power, labor, ritual, and space.', 0),
  ('1fb24917-eb55-49c7-ace1-d15ba29167a2', 'd2e3f4a5-6b7c-4d92-9e12-2f3a4b5c6d32', '1c14e279-b4c5-4af2-823a-6865ec4ca46b', 'concept'::public.curated_course_node_type, 'Indus Valley', null, 0),
