  ('a53cfaff-3fc4-4b82-9109-cab1b50847f7', 'd2e3f4a5-6b7c-4d92-9e12-2f3a4b5c6d32', '1c14e279-b4c5-4af2-823a-6865ec4ca46b', 'concept'::public.curated_course_node_type, 'Early Southeast Asian polities', null, 2),
