  ('ef2fe401-eeee-4101-956f-8cdb30b33669', 'd2e3f4a5-6b7c-4d92-9e12-2f3a4b5c6d32', '8778c940-ef19-40b1-965f-c60c89f8516b', 'concept'::public.curated_course_node_type, 'Steppe-sedentary interaction', null, 2),
  ('4bb8ce50-99db-4578-9da8-338b69279723', 'd2e3f4a5-6b7c-4d92-9e12-2f3a4b5c6d32', null, 'topic'::public.curated_course_node_type, 'Religions, Ideas, and Cultural Worlds', 'Religion and thought are treated here as institutions, ethical systems, social practices, and transregional networks. Students learn to connect belief, patronage, law, art, pilgrimage, and political legitimacy.', 2),
  ('d2f85aae-026e-487f-bac5-dc472cb2ac48', 'd2e3f4a5-6b7c-4d92-9e12-2f3a4b5c6d32', '4bb8ce50-99db-4578-9da8-338b69279723', 'subtopic'::public.curated_course_node_type, 'Buddhist circulation', 'Students examine Buddhism as a mobile tradition shaped by translation, monastic networks, patronage, and local adaptation.', 0),
