  ('47e8d177-b8fd-4ebb-be1e-030c7a98abad', 'd2e3f4a5-6b7c-4d92-9e12-2f3a4b5c6d32', null, 'topic'::public.curated_course_node_type, 'Imperial Formations and Inner Asian Connections', 'This section makes Inner Asia central rather than peripheral. Students study empires as mobile, negotiated systems that connected agrarian states, pastoral worlds, commercial routes, and military technologies.', 3),
