  ('9583be4e-51f7-45d2-9765-93ddcbecbf5d', 'd2e3f4a5-6b7c-4d92-9e12-2f3a4b5c6d32', '9a6cf828-c531-4965-8e15-da918e67fa68', 'subtopic'::public.curated_course_node_type, 'Regional polities and social worlds', 'Students learn how political authority interacted with caste, kinship, landholding, and religious patronage.', 0),
