  ('60170e15-0dbf-4875-a714-824b2cf5da11', 'd2e3f4a5-6b7c-4d92-9e12-2f3a4b5c6d32', null, 'topic'::public.curated_course_node_type, 'Reform, Revolution, Nationalism, and State-Building', 'Students examine how Asian intellectuals, activists, workers, peasants, soldiers, and elites answered the crisis of empire. The goal is to compare political imaginaries without assuming a single path to modernity.', 9),
